                {"id": "a1ga12", "prompt": "___ case sono grandi. (the houses, f. pl.)", "answers": [["Le"]], "explanation": "Le is the plural definite article for feminine nouns.", "options": ["Le", "I", "Gli"]},
                {"id": "a1ga13", "prompt": "Ho ___ libro interessante. (an interesting book, indefinite m.)", "answers": [["un"]], "explanation": "Un is the plain masculine indefinite article before a consonant.", "options": ["un", "uno", "una"]},
                {"id": "a1ga14", "prompt": "___ acqua è fredda. (the water, definite f. before vowel)", "answers": [["L'"]], "explanation": "Feminine la shortens to l' before a vowel.", "options": ["La", "L'", "Lo"]},
                {"id": "a1ga15", "prompt": "___ amico arriva domani. (a male friend, indefinite m. before vowel)", "answers": [["Un"]], "explanation": "Masculine un never takes an apostrophe, even before a vowel.", "options": ["Un", "Un'", "Uno"]},
