                {"id": "a1ea13", "prompt": "Tu ___ ragione.", "answers": [["hai"]], "explanation": "Avere ragione — to be right — needs avere: hai.", "options": ["hai", "sei", "ha"]},
                {"id": "a1ea14", "prompt": "Noi ___ stanchi oggi.", "answers": [["siamo"]], "explanation": "Noi + essere (characteristic) = siamo.", "options": ["siamo", "abbiamo", "sono"]},
                {"id": "a1ea15", "prompt": "Lei ___ paura dei ragni.", "answers": [["ha"]], "explanation": "Avere paura — to be afraid — needs avere: ha.", "options": ["ha", "è", "hai"]},
                {"id": "a1ea16", "prompt": "Io ___ di Palermo.", "answers": [["sono"]], "explanation": "Origin uses essere: io + essere = sono.", "options": ["sono", "ho", "sei"]},
