                {"id": "a1ps20", "prompt": "Marta studia il francese. ___ invece studia il tedesco.", "answers": [["Lei"]], "explanation": "Kept for clarity, referring back to Marta.", "options": ["Lei", "Lui", "Loro"]},
                {"id": "a1ps21", "prompt": "Non lo so io, lo sa ___.", "answers": [["lui"]], "explanation": "Kept for contrast with io earlier in the sentence.", "options": ["lui", "io", "noi"]},
