                {"id": "a1pr14", "prompt": "Loro ___ (pulire) la casa il sabato.", "answers": [["puliscono"]], "explanation": "Pulire is an -isc- verb: loro form is puliscono.", "options": ["puliscono", "puliamo", "pulite"]},
                {"id": "a1pr15", "prompt": "Tu e Marco ___ (lavorare) insieme?", "answers": [["lavorate"]], "explanation": "Voi + -are verb = -ate ending.", "options": ["lavorate", "lavoriamo", "lavorano"]},
